SELECT *
FROM (
  SELECT ROWNUM AS rnum, a.*
  FROM (
    SELECT notice_no, admin_no, notice_title, view_count,
           is_fixed, created_date, updated_date, notice_file
    FROM notices
    ORDER BY is_fixed DESC, notice_no DESC
  ) a
  WHERE ROWNUM <= #{end}
)
WHERE rnum >= #{start}

