SELECT qna_no, user_no, qna_title, qna_content, qna_file, 
       is_answered, created_date, user_name
FROM (
    SELECT ROWNUM AS rnum, q.*
    FROM (
        SELECT qna_no, user_no, qna_title, qna_content, qna_file,
               is_answered, created_date, user_name
        FROM qna_board
        ORDER BY qna_no DESC
    ) q
    WHERE ROWNUM <= #{end}
)
WHERE rnum >= #{start}
